static void MJ_convin_45(const double* x0){
  for(int f=0;f<91125;f++){
    int sp = MJ_SPOS45[f];
    _mm_prefetch((const char*)(MJ_S45_re + MJ_SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    _mm_prefetch((const char*)(MJ_S45_im + MJ_SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    MJ_S45_re[sp] = x0[2*f];
    MJ_S45_im[sp] = x0[2*f+1];
  }
}
static void MJ_convc_45(const double* c){
  for(int f=0;f<91125;f++){
    int tp = MJ_TPOS45[f];
    _mm_prefetch((const char*)(MJ_CT45_re + MJ_TPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    _mm_prefetch((const char*)(MJ_CT45_im + MJ_TPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    MJ_CT45_re[tp] = c[2*f];
    MJ_CT45_im[tp] = c[2*f+1];
  }
}
static void MJ_convout_45(double* out){
  for(int f=0;f<91125;f++){
    int sp = MJ_SPOS45[f];
    _mm_prefetch((const char*)(MJ_S45_re + MJ_SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    _mm_prefetch((const char*)(MJ_S45_im + MJ_SPOS45[f+24 < 91125 ? f+24 : f]), _MM_HINT_T0);
    out[2*f]   = MJ_S45_re[sp];
    out[2*f+1] = MJ_S45_im[sp];
  }
}
uint64_t MJ_bench_45(int which, long reps){
  uint64_t t0 = __rdtsc();
  for(long r=0;r<reps;r++){ if(which==0) MJ_phaseA_45(); else MJ_phaseB_45(); }
  return __rdtsc() - t0;
}
void MJ_run_45(const double* x0, const double* c, double* one, double* fin, long B, long m){
  for(long b=0;b<B;b++){
    MJ_convin_45(x0 + b*2*91125);
    MJ_convc_45(c + b*2*91125);
    for(long s=0;s<m;s++){
      MJ_phaseA_45();
      MJ_phaseB_45();
      if(s==0) MJ_convout_45(one + b*2*91125);
    }
    MJ_convout_45(fin + b*2*91125);
  }
}
